function apa(item){ var a=item.authors?item.authors.join(', '):'Anonymous';
  if(item.type==='article') return a+' ('+item.year+'). '+item.title+'. '+item.journal+'.';
  return a+' ('+item.year+'). '+item.title+'. '+(item.publisher||'')+'.';
}
var EXPORTS={apa:apa};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BibliographyForgePure = EXPORTS; }
